"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["87671"],{2314(n){n.exports=JSON.parse('{"id":1034,"title":"20\u4E2AChatGPT\u63D0\u793A\u8BCD\uFF0C\u6BCF\u5468\u8BA9\u4F60\u591A\u51FA 20 \u5C0F\u65F6\u81EA\u7531\u65F6\u95F4","description":"1. \u7528 80/20 \u539F\u5219\u6307\u5BFC\u5B66\u4E60\\n\\n\u63D0\u793A\uFF1A\u201C\u6211\u60F3\u4E86\u89E3 [\u63D2\u5165\u4E3B\u9898]\u3002\u786E\u5B9A\u5E76\u5206\u4EAB\u4ECE\u8BE5\u4E3B\u9898\u4E2D\u5B66\u5230\u7684\u6700\u91CD\u8981\u7684 20%\uFF0C\u8FD9\u5C06\u5E2E\u52A9\u6211\u7406\u89E3\u5176\u4E2D\u7684 80%\u3002\u201C\\n\\n\u4E2D\u6587\u7248\uFF1A\u201C\u6211\u60F3\u4E86\u89E3[\u63D2\u5165\u4E3B\u9898]\u3002\u786E\u5B9A\u5E76\u5206\u4EAB\u4ECE\u8FD9\u4E2A\u4E3B\u9898\u4E2D\u5B66\u5230\u7684\u6700\u91CD\u8981\u768420%\uFF0C\u8FD9\u5C06\u6709\u52A9\u4E8E\u6211\u7406\u89E3\u5176\u4E2D\u768480%\u3002\\n\\n\\n2. \u6821\u5BF9+\u6DA6\u8272\u4F60\u7684\u521B\u4F5C\\n\\nPrompt\uFF1A[\u7C98\u8D34\u4F60\u7684\u521B\u4F5C]\u201C\u6821\u5BF9\u6211\u4E0A\u9762\u7684\u5199\u4F5C\u3002\u4FEE\u6B63\u8BED\u6CD5\u548C\u62FC\u5199\u9519\u8BEF\u3002\u5E76\u63D0\u51FA\u53EF\u4EE5\u63D0\u9AD8\u6211\u5199\u4F5C\u6E05\u6670\u5EA6\u7684\u5EFA\u8BAE\u3002\u201C\\n\\n\u4E2D\u6587\u7248\uFF1A\u201C\u6821\u5BF9\u6211\u4E0A\u9762\u7684\u6587\u7AE0\u3002\u4FEE\u6B63\u8BED\u6CD5\u548C\u62FC\u5199\u9519\u8BEF\u3002\u5E76\u63D0\u51FA\u5EFA\u8BAE\uFF0C\u4EE5\u63D0\u9AD8\u6211\u5199\u4F5C\u7684\u6E05\u6670\u5EA6\u201D\\n\\n3. \u8BA9 ChatGPT \u5316\u8EAB\u4F60\u7684\u52A9\u7406\\n\\nPrompt\uFF1A\u201C\u6211\u6B63\u5728\u521B\u5EFA\u4E00\u4EFD\u5173\u4E8E [\u63D2\u5165\u4E3B\u9898] \u7684\u62A5\u544A\u3002\u7814\u7A76\u5E76\u521B\u5EFA\u4E00\u4EFD\u5E26\u6709\u5206\u6B65\u6307\u5357\u7684\u6DF1\u5165\u62A5\u544A\uFF0C\u8FD9\u5C06\u5E2E\u52A9\u8BFB\u8005\u4E86\u89E3\u5982\u4F55 [\u63D2\u5165\u7ED3\u679C]\u3002\u201C\\n\\n\u4E2D\u6587\u7248\uFF1A\u201C\u6211\u6B63\u5728\u64B0\u5199\u5173\u4E8E[\u63D2\u5165\u4E3B\u9898]\u7684\u62A5\u544A\u3002\u7814\u7A76\u5E76\u521B\u5EFA\u5E26\u6709\u5206\u6B65\u6307\u5357\u7684\u6DF1\u5165\u62A5\u544A\uFF0C\u4EE5\u5E2E\u52A9\u8BFB\u8005\u4E86\u89E3\u5982\u4F55[\u63D2\u5165\u7ED3\u679C]\u3002\\n\\n4. \u5FEB\u901F\u5B66\u4E60\u65B0\u6280\u80FD\\n\\n\u63D0\u793A\uFF1A\u201C\u6211\u60F3\u5B66\u4E60[\u63D2\u5165\u60F3\u8981\u7684\u6280\u80FD]\u3002\u5236\u5B9A\u4E00\u4E2A 30 \u5929\u7684\u5B66\u4E60\u8BA1\u5212\uFF0C\u5E2E\u52A9\u50CF\u6211\u8FD9\u6837\u7684\u521D\u5B66\u8005\u5B66\u4E60\u548C\u63D0\u9AD8\u8FD9\u9879\u6280\u80FD\u3002\u201C\\n\\n\u4E2D\u6587\u7248\uFF1A\u201C\u6211\u60F3\u5B66[\u63D2\u5165\u6240\u9700\u6280\u80FD].\u5236\u5B9A\u4E00\u4E2A 30 \u5929\u7684\u5B66\u4E60\u8BA1\u5212\uFF0C\u5E2E\u52A9\u50CF\u6211\u8FD9\u6837\u7684\u521D\u5B66\u8005\u5B66\u4E60\u548C\u63D0\u9AD8\u8FD9\u9879\u6280\u80FD\u3002\\n\\n\\n5. \u901A\u8FC7\u81EA\u6211\u6D4B\u8BD5\u52A0\u5F3A\u5B66\u4E60\\n\\n\u63D0\u793A\uFF1A\u201C\u6211\u76EE\u524D\u6B63\u5728\u5B66\u4E60[\u63D2\u5165\u4E3B\u9898]\u3002\u95EE\u6211\u4E00\u7CFB\u5217\u95EE\u9898\u6765\u6D4B\u8BD5\u6211\u7684\u77E5\u8BC6\u3002\u627E\u51FA\u6211\u7B54\u6848\u4E2D\u7684\u77E5\u8BC6\u7A7A\u767D\uFF0C\u5E76\u7ED9\u6211\u66F4\u597D\u7684\u7B54\u6848\u6765\u586B\u8865\u8FD9\u4E9B\u7A7A\u767D\u3002\u201C\\n\\n\u4E2D\u6587\u7248\uFF1A\u201C\u6211\u76EE\u524D\u6B63\u5728\u5B66\u4E60[\u63D2\u5165\u4E3B\u9898]\u3002\u95EE\u6211\u4E00\u7CFB\u5217\u95EE\u9898\uFF0C\u8FD9\u4E9B\u95EE\u9898\u5C06\u6D4B\u8BD5\u6211\u7684\u77E5\u8BC6\u3002\u627E\u51FA\u6211\u7B54\u6848\u4E2D\u7684\u77E5\u8BC6\u5DEE\u8DDD\uFF0C\u5E76\u7ED9\u6211\u66F4\u597D\u7684\u7B54\u6848\u6765\u586B\u8865\u8FD9\u4E9B\u7A7A\u767D\u3002\\n\\n6. \u8BA9 ChatGPT \u5E2E\u4F60\u751F\u6210\u63D0\u793A\\n\\nPrompt\uFF1A\u201C\u4F60\u662F\u4E00\u4E2A\u65E8\u5728\u5E2E\u52A9 [\u63D2\u5165\u4E13\u4E1A] \u7684 AI\uFF0C\u751F\u6210 10 \u4E2A\u6700\u4F73\u63D0\u793A\u5217\u8868\u3002\u63D0\u793A\u5E94\u8BE5\u4E0E [\u63D2\u5165\u4E3B\u9898] \u6709\u5173\u3002\u201C\\n\\n\u4E2D\u6587\u7248\uFF1A\u201C\u4F60\u662F\u4E00\u4E2A\u65E8\u5728\u5E2E\u52A9[\u63D2\u5165\u804C\u4E1A]\u7684AI\u3002\u4E3A\u81EA\u5DF1\u751F\u6210 10 \u4E2A\u6700\u4F73\u63D0\u793A\u7684\u5217\u8868\u3002\u63D0\u793A\u5E94\u8BE5\u662F\u5173\u4E8E[\u63D2\u5165\u4E3B\u9898]\u7684\u3002\\n\\n7. \u8BA9 ChatGPT \u5E2E\u4F60\u66F4\u597D\u5730\u4F7F\u7528 ChatGPT\\n\\nPrompt\uFF1A\u201C\u521B\u5EFA\u4F7F\u7528 ChatGPT \u7684\u521D\u5B66\u8005\u6307\u5357\u3002\u4E3B\u9898\u5E94\u5305\u62EC\u63D0\u793A\u3001\u542F\u52A8\u548C\u89D2\u8272\u3002\u5305\u62EC\u793A\u4F8B\u3002\u6307\u5357\u4E0D\u5E94\u8D85\u8FC7 500 \u4E2A\u5355\u8BCD\u3002\u201C\\n\\n\u4E2D\u6587\u7248\uFF1A\u201C\u521B\u5EFA\u4F7F\u7528ChatGPT\u7684\u521D\u5B66\u8005\u6307\u5357.\u4E3B\u9898\u5E94\u5305\u62EC\u63D0\u793A\u3001\u542F\u52A8\u548C\u89D2\u8272\u3002\u5305\u62EC\u793A\u4F8B\u3002\u6307\u5357\u4E0D\u5E94\u8D85\u8FC7500\u5B57\u3002\\n\\n\\n8. \u5FEB\u901F\u5B66\u4E60\u65B0\u77E5\u8BC6\u3001\u65B0\u6982\u5FF5\\n\\nPrompt\uFF1A\u201C\u7528\u4EFB\u4F55\u521D\u5B66\u8005\u90FD\u80FD\u7406\u89E3\u7684\u7B80\u5355\u6613\u61C2\u7684\u672F\u8BED\u89E3\u91CA[\u63D2\u5165\u4E3B\u9898]\u3002\u201C\\n\\n\u4E2D\u6587\u7248\uFF1A\u201C\u7528\u4EFB\u4F55\u521D\u5B66\u8005\u90FD\u80FD\u7406\u89E3\u7684\u7B80\u5355\u6613\u61C2\u7684\u8BED\u8A00\u89E3\u91CA[\u63D2\u5165\u4E3B\u9898]\u3002\\n\\n9. \u5934\u8111\u98CE\u66B4\\n\\n\u63D0\u793A\uFF1A\u201C\u6211\u60F3[\u63D2\u5165\u4EFB\u52A1\u6216\u76EE\u6807]\u3002\u4E3A[\u63D2\u5165\u4EFB\u52A1\u6216\u76EE\u6807]\u751F\u6210[\u63D2\u5165\u671F\u671B\u7684\u7ED3\u679C]\u3002\u201C\\n\\n\u4E2D\u6587\u7248\uFF1A\u201C\u6211\u60F3[\u63D2\u5165\u4EFB\u52A1\u6216\u76EE\u6807]\u3002\u4E3A [\u63D2\u5165\u4EFB\u52A1\u6216\u76EE\u6807] \u751F\u6210 [\u63D2\u5165\u6240\u9700\u7ED3\u679C]\u3002\\n\\n\\n10. \u603B\u7ED3\u957F\u6587\u6863\u548C\u6587\u7AE0\\n\\nPrompt\uFF1A\u201C\u603B\u7ED3\u4E0B\u9762\u7684\u6587\u5B57\uFF0C\u5E76\u7ED9\u6211\u4E00\u4EFD\u5305\u542B\u5173\u952E\u89C1\u89E3\u548C\u6700\u91CD\u8981\u4E8B\u5B9E\u7684\u8981\u70B9\u5217\u8868\u3002\u201C [\u63D2\u5165\u6587\u5B57]\\n\\n\u4E2D\u6587\u7248\uFF1A\u201C\u603B\u7ED3\u4E0B\u9762\u7684\u6587\u5B57\uFF0C\u7ED9\u6211\u4E00\u4E2A\u8981\u70B9\u5217\u8868\uFF0C\u5305\u62EC\u5173\u952E\u89C1\u89E3\u548C\u6700\u91CD\u8981\u7684\u4E8B\u5B9E\u3002\\n\\n11. \u8BA9 ChatGPT \u5E2E\u4F60\u89E3\u51B3\u95EE\u9898\\n\\nPrompt\uFF1A[\u63D2\u5165\u95EE\u9898]\u201C\u7ED9\u6211\u4E00\u4E2A\u89E3\u51B3\u4E0A\u8FF0\u95EE\u9898\u7684\u6B65\u9AA4\uFF0C\u5E76\u6E05\u695A\u5730\u8BF4\u660E\u5982\u4F55\u6267\u884C\u6BCF\u4E2A\u6B65\u9AA4\u3002\u201C\\n\\n\u4E2D\u6587\u7248\uFF1A\u201C\u7ED9\u6211\u4E00\u4E2A\u9488\u5BF9\u4E0A\u8FF0\u95EE\u9898\u7684\u5206\u6B65\u89E3\u51B3\u65B9\u6848\uFF0C\u5E76\u660E\u786E\u8BF4\u660E\u5982\u4F55\u6267\u884C\u6BCF\u4E2A\u6B65\u9AA4\u3002\\n\\n12. \u51B3\u7B56\u8BC4\u4F30\\n\\n\u63D0\u793A\uFF1A\u201C\u6211\u6B63\u5728\u5C1D\u8BD5[\u63D2\u5165\u51B3\u5B9A]\u3002\u7ED9\u6211\u4E00\u4EFD\u5229\u5F0A\u6E05\u5355\uFF0C\u8FD9\u5C06\u5E2E\u52A9\u6211\u51B3\u5B9A\u4E3A\u4EC0\u4E48\u6211\u5E94\u8BE5\u6216\u4E0D\u5E94\u8BE5\u505A\u51FA\u8FD9\u4E2A\u51B3\u5B9A\u3002\u201C\\n\\n\u4E2D\u6587\u7248\uFF1A\u201C\u6211\u6B63\u5728\u5C1D\u8BD5\u51B3\u5B9A\u662F\u5426\u5E94\u8BE5[\u63D2\u5165\u51B3\u5B9A]\u3002\u7ED9\u6211\u4E00\u4EFD\u5229\u5F0A\u6E05\u5355\uFF0C\u5E2E\u52A9\u6211\u51B3\u5B9A\u4E3A\u4EC0\u4E48\u6211\u5E94\u8BE5\u6216\u4E0D\u5E94\u8BE5\u505A\u51FA\u8FD9\u4E2A\u51B3\u5B9A\u3002\\n\\n\\n13. \u5FEB\u901F\u9605\u8BFB\u56FE\u4E66\\n\\nPrompt\uFF1A\u201C\u603B\u7ED3[\u63D2\u5165\u4F5C\u8005]\u7684[\u63D2\u5165\u4E66]\uFF0C\u5E76\u7ED9\u6211\u5217\u51FA\u6700\u91CD\u8981\u7684\u5B66\u4E60\u548C\u89C1\u89E3\u3002\u201D\\n\\n\u82F1\u6587\u7248\uFF1A\\"Summarize the book [insert book] by the author [insert author] and give me a list of the most important learnings and insights.\\"\\n\\n14. \u6545\u4E8B+\u9690\u55BB\uFF0C\u8F85\u52A9\u5FEB\u901F\u8BB0\u5FC6\\n\\nPrompt\uFF1A\u201C\u6211\u76EE\u524D\u6B63\u5728\u5B66\u4E60[\u63D2\u5165\u4E3B\u9898]\u3002\u5C06\u8FD9\u4E2A\u4E3B\u9898\u7684\u4E3B\u8981\u77E5\u8BC6\u70B9\u8F6C\u5316\u4E3A\u5F15\u4EBA\u5165\u80DC\u7684\u6545\u4E8B\u548C\u9690\u55BB\u6765\u5E2E\u52A9\u6211\u8BB0\u5FC6\u3002\u201D\\n\\n\u82F1\u6587\u7248\uFF1A\\"I am currently learning about [insert topic]. Convert the key lessons from this topic into engaging stories and metaphors to aid my memorization.\\"\\n\\n15. \u5E2E\u52A9\u8D77\u6807\u9898\\n\\nPrompt\uFF1A\u201C\u6211\u6B63\u5728\u5199\u4E00\u7BC7\u5173\u4E8E[\u63D2\u5165\u4E3B\u9898]\u7684\u6587\u7AE0\u3002\u6211\u60F3\u4E0D\u51FA\u4E00\u4E2A\u5438\u5F15\u4EBA\u7684\u6807\u9898\u3002\u8BF7\u7ED9\u6211\u4E00\u4EFD\u5173\u4E8E\u8FD9\u7BC7\u6587\u7AE0\u6807\u9898\u7684 5 \u6761\u5EFA\u8BAE\u6E05\u5355\u3002\u201D\\n\\n\u82F1\u6587\u7248\uFF1A\\"I\'m writing a blog post about [insert topic]. I can\'t come up with a catchy title. Give me a list of 5 suggestions for the blog title for this piece.\\"\\n\\n\\n16. \u5411\u6700\u4F18\u79C0\u7684\u4EBA\u5B66\u4E60\\n\\nPrompt\uFF1A\u201C\u5206\u6790[\u63D2\u5165\u4F60\u7684\u5DE5\u4F5C\u9886\u57DF]\u4E2D\u8868\u73B0\u6700\u597D\u7684\u4EBA\u3002\u7ED9\u6211\u4E00\u4EFD\u6E05\u5355\uFF0C\u5217\u51FA\u6211\u53EF\u4EE5\u4ECE\u8FD9\u4E9B\u8868\u73B0\u6700\u597D\u7684\u4EBA\u8EAB\u4E0A\u5B66\u5230\u7684\u6700\u91CD\u8981\u7684\u7ECF\u9A8C\u6559\u8BAD\uFF0C\u4EE5\u63D0\u9AD8\u6211\u7684\u5DE5\u4F5C\u6548\u7387\u3002\u201D\\n\\n\u82F1\u6587\u7248\uFF1A\\"Analyze the top performers in [insert your field of work]. Give me a list of the most important lessons I can learn from these top performers to boost my productivity.\\"\\n\\n17. \u8F85\u52A9\u9762\u8BD5\\n\\nPrompt\uFF1A\u201C\u6211\u6B63\u5728\u9762\u8BD5 [enter position]\u3002\u4F60\u80FD\u7ED9\u6211\u4E00\u4EFD\u9762\u8BD5\u5B98\u5728\u8FD9\u6B21\u9762\u8BD5\u4E2D\u4F1A\u95EE\u6211\u7684\u95EE\u9898\u7684\u5B8C\u6574\u6E05\u5355\u5417\uFF1F\u540C\u65F6\u7B80\u8981\u56DE\u7B54\u6BCF\u4E2A\u95EE\u9898\u3002\u201D\\n\\n\u82F1\u6587\u7248\uFF1A\\"I am interviewing for [enter position]. Can you give me a comprehensive list of questions interviewers will ask me during this interview. Also provide brief answers to each question.\\"\\n\\n\\n18. \u521B\u5EFA\u4EFB\u4F55\u5F62\u5F0F\u7684\u6587\u672C\u6216\u5185\u5BB9\\n\\nPrompt\uFF1A\u201C\u4E3B\u9898\uFF1A\u5982\u4F55\u6709\u8BF4\u670D\u529B\u5730\u5199\u4F5C\\n\u542C\u4F17\uFF1A\u4F01\u4E1A\u9AD8\u7BA1\\n\u683C\u5F0F\uFF1A[PPT/Word/Excel\u2026\u2026]\\n\u6F14\u8BB2\u8BED\u6C14\uFF1A\u6559\u80B2\u548C\u9F13\u821E\u4EBA\u5FC3\\n\u76EE\u6807\uFF1A\u6FC0\u53D1\u542C\u4F17\u6709\u6548\u5199\u4F5C\\n\u9644\u52A0\u8BF4\u660E\uFF1A\u6F14\u8BB2\u5E94\u5728 15 \u5206\u949F\u4EE5\u5185\u201D\\n\\n\u82F1\u6587\u7248\uFF1A\\"Topic: How to write persuasively\\nAudience: Business executives\\nFormat: Speech\\nTone: Educational and inspiring\\nGoal: Inspire the audience to write effectively\\nAdditional instructions: The speech should be under 15 minutes\\"\\n\\n19. \u6A21\u4EFF\u521B\u4F5C\\n\\nPrompt\uFF1A\u201C\u4ECE\u4E0B\u9762\u7684\u6587\u5B57\u5206\u6790\u5199\u4F5C\u98CE\u683C\uFF0C\u5E76\u5199\u4E00\u7BC7\u5173\u4E8E [\u63D2\u5165\u4E3B\u9898] \u7684 200 \u5B57\u6587\u7AE0\u6307\u5357\u201D [\u63D2\u5165\u4F60\u7684\u6587\u5B57]\\n\\n\u82F1\u6587\u7248\uFF1A\\"Analyze the writing style from the text below and write a 200 word piece guide on [insert topic]\\"\\n\\n20. \u5185\u5BB9\u91CD\u5199\\n\\nPrompt\uFF1A\u201C\u91CD\u5199\u4E0B\u9762\u7684\u6587\u5B57\uFF0C\u8BA9\u521D\u5B66\u8005\u5BB9\u6613\u7406\u89E3\u201D\u3002[\u63D2\u5165\u6587\u5B57]\\n\\n\u82F1\u6587\u7248\uFF1A\\"Rewrite the text below and make it easy for a beginner to understand\\".","owner":"fjh7912","upvotes":70,"downvotes":1,"upvoteDifference":69,"updatedAt":"2026-08-18T08:49:04.449Z"}')}}]);